{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    by_id = {node["id"]: node for node in nodes}
    retained = {node["id"] for node in nodes if not node.get("removable", False)}

    for symbol in case.get("required_symbols", []):
        candidates = [node for node in nodes if node.get("symbol") == symbol]
        if candidates:
            best = max(candidates, key=lambda node: node.get("utility", 0))
            retained.add(best["id"])

    pending = list(retained)
    while pending:
        node_id = pending.pop()
        node = by_id.get(node_id)
        if node is None:
            continue
        parent_id = node.get("parent")
        if parent_id is not None and parent_id in by_id and parent_id not in retained:
            retained.add(parent_id)
            pending.append(parent_id)

    return {
        "removed_node_ids": [node["id"] for node in nodes if node["id"] not in retained],
        "retained_node_ids": [node["id"] for node in nodes if node["id"] in retained],
    }
"}
